// If the battle context exists and the Kjata resource handle is zero, initializes a default-
// duration record, builds SUMMON/KJATA, requests resource type 31 using the scene's model-table
// bank and registers its sound groups. The record lives in a block of stack locals.
// FUNCTION: FF7 0x004f97f0
void __cdecl BattleFx_SummonLoadResKjata(void)
{
    GfxModelTableBank *context;
    GfxResourceRequest requestBuffer;
    int kind;
    char pathSize[200];
    GfxResourceRequest *pReq;
    int defsPtr;

    if (g_pBattle3dScene != 0 && g_BattleSummonKjataTableCursor == 0) {
        kind = 0x1F;
        defsPtr = (int)&g_BattleSummonKjataResourceDefs;
        context = (GfxModelTableBank *)(g_pBattle3dScene->modelTableBank);
        pReq = &requestBuffer;
        Gfx_InitResourceRequest(pReq);
        pReq->groupTag = 0;
        // STRING: FF7 0x0087b700
        pReq->resourcePath = BattleFx_BuildResourcePath("SUMMON/KJATA", pathSize);
        Gfx_LoadModelTableIfAbsent(kind, defsPtr, pReq, &g_BattleSummonKjataTableCursor, context);
        SfxRegisterSoundGroups((struct SoundGroup **)&g_BattleSummonKjataResourceTable);
    }
}

#pragma intrinsic(memcpy)
// Restores the 0x1624-byte vertex data g_BattleSummonKjataVertexData1 from g_BattleSummonKjataVertexData2,
// clears three translation ints, three rotation shorts and seven shared state values, then loads
// the Kjata resources. Calls BattleFx_SummonBeginKjata with both arguments and returns zero.
// FUNCTION: FF7 0x004f9891
int __cdecl BattleFx_SummonEnterKjata(int targetMask, int actorIdx)
{
    memcpy((void *)&(g_BattleSummonKjataVertexData1.triangleOffset), (void *)&g_BattleSummonKjataVertexData2, 5668);
    g_BattleSummonKjataLightMatrix.t[2] = 0;
    g_BattleSummonKjataLightMatrix.t[1] = g_BattleSummonKjataLightMatrix.t[2];
    g_BattleSummonKjataLightMatrix.t[0] = g_BattleSummonKjataLightMatrix.t[1];
    g_BattleSummonKjataCameraTable.vz = 0;
    g_BattleSummonKjataCameraTable.vy = g_BattleSummonKjataCameraTable.vz;
    g_BattleSummonKjataCameraTable.vx = g_BattleSummonKjataCameraTable.vy;
    g_BattleSummonKjataTrailNodeCount = 0;
    g_BattleSummonKjataLoadedResIndex = 0;
    g_BattleSummonKjataParticleIndex = 0;
    g_BattleSummonKjataWaveBank = 0;
    g_BattleSummonKjataSpawnAngle = 0;
    BattleFx_SummonLoadResKjata();
    BattleFx_SummonBeginKjata(targetMask, actorIdx);
    return 0;
}
