                    Gfx_ShadePsxTriVertexColors((CVECTOR *)(src.addr + 8), (CVECTOR *)(src.addr + 0xC), (CVECTOR *)(src.addr + 0x10), kjataDraw->vertexShade, &prevPrim->color0, &prevPrim->color1, &prevPrim->color2);
                    Gfx_ShadePsxVertexColor((CVECTOR *)(src.addr + 0x14), kjataDraw->vertexShade, &prevPrim->color3);
